import{_ as i,c as t,o as l,ag as e}from"./chunks/framework.DfL_BkQ-.js";const u=JSON.parse('{"title":"使用指南","description":"","frontmatter":{},"headers":[],"relativePath":"zh-TW/guide/usage.md","filePath":"zh-TW/guide/usage.md","lastUpdated":1794112334000}'),r={name:"zh-TW/guide/usage.md"};function o(d,a,n,h,s,c){return l(),t("div",null,[...a[0]||(a[0]=[e('<h1 id="使用指南" tabindex="-1">使用指南 <a class="header-anchor" href="#使用指南" aria-label="Permalink to &quot;使用指南&quot;">​</a></h1><h2 id="基礎導覽" tabindex="-1">基礎導覽 <a class="header-anchor" href="#基礎導覽" aria-label="Permalink to &quot;基礎導覽&quot;">​</a></h2><h3 id="開啟圖片" tabindex="-1">開啟圖片 <a class="header-anchor" href="#開啟圖片" aria-label="Permalink to &quot;開啟圖片&quot;">​</a></h3><ul><li><strong>檔案選單</strong>：點擊 檔案 &gt; 開啟，選取單張圖片</li><li><strong>檔案夾檢視</strong>：點擊 檔案 &gt; 開啟檔案夾，瀏覽整個目錄</li><li><strong>拖放</strong>：把圖片檔案或檔案夾直接拖到應用程式視窗中</li><li><strong>Chrome 擴充功能</strong>：在任意網站上點擊擴充功能圖示即可檢視全部圖片</li></ul><h2 id="finder-同步擴充功能" tabindex="-1">Finder 同步擴充功能 <a class="header-anchor" href="#finder-同步擴充功能" aria-label="Permalink to &quot;Finder 同步擴充功能&quot;">​</a></h2><h3 id="在-finder-中快速處理圖片" tabindex="-1">在 Finder 中快速處理圖片 <a class="header-anchor" href="#在-finder-中快速處理圖片" aria-label="Permalink to &quot;在 Finder 中快速處理圖片&quot;">​</a></h3><p>Finder 同步擴充功能會在 Finder 工具列中加入一個 Nicasa 按鈕，用於快速處理圖片：</p><ol><li>在 Finder 中選取一張或多張圖片</li><li>點擊 Nicasa 工具列按鈕</li><li>選擇 <strong>圖片最佳化工具</strong> 以壓縮檔案，或選擇 <strong>AI 影像編輯器</strong> 以增強圖片</li><li>Nicasa 會自動開啟並處理選取的檔案</li></ol><h3 id="支援的格式" tabindex="-1">支援的格式 <a class="header-anchor" href="#支援的格式" aria-label="Permalink to &quot;支援的格式&quot;">​</a></h3><p>該擴充功能支援：JPG、PNG、GIF、BMP、WebP、SVG、TIFF 和 ICO 檔案。</p><h3 id="縮圖檢視" tabindex="-1">縮圖檢視 <a class="header-anchor" href="#縮圖檢視" aria-label="Permalink to &quot;縮圖檢視&quot;">​</a></h3><p>主介面以縮圖形式展示你的圖片：</p><ul><li><strong>單擊</strong>：選取一張圖片</li><li><strong>連按兩下</strong>：以完整檢視開啟</li><li><strong>按右鍵</strong>：呼出帶選項的快速選單</li></ul><h3 id="完整檢視模式" tabindex="-1">完整檢視模式 <a class="header-anchor" href="#完整檢視模式" aria-label="Permalink to &quot;完整檢視模式&quot;">​</a></h3><p>在全螢幕檢視圖片時：</p><ul><li><strong>縮放</strong>：使用滑鼠滾輪或縮放控制項</li><li><strong>平移</strong>：在放大後的圖片上按住拖曳</li><li><strong>切換</strong>：使用方向鍵或螢幕按鈕切換到上一張/下一張</li></ul><h2 id="截圖功能" tabindex="-1">截圖功能 <a class="header-anchor" href="#截圖功能" aria-label="Permalink to &quot;截圖功能&quot;">​</a></h2><h3 id="截圖" tabindex="-1">截圖 <a class="header-anchor" href="#截圖" aria-label="Permalink to &quot;截圖&quot;">​</a></h3><ol><li>點擊工具列中的截圖按鈕，或使用鍵盤快速鍵</li><li>選取你想要擷取的區域</li><li>截圖會自動在 Nicasa 中開啟，方便立即編輯</li></ol><h3 id="螢幕錄製權限" tabindex="-1">螢幕錄製權限 <a class="header-anchor" href="#螢幕錄製權限" aria-label="Permalink to &quot;螢幕錄製權限&quot;">​</a></h3><p>截圖功能需要螢幕錄製權限：</p><ol><li>進入 系統設定 &gt; 隱私權與安全性 &gt; 螢幕錄製</li><li>勾選 Nicasa 旁邊的註記框</li><li>如有必要，重新啟動 Nicasa</li></ol><h2 id="ai-影像編輯器" tabindex="-1">AI 影像編輯器 <a class="header-anchor" href="#ai-影像編輯器" aria-label="Permalink to &quot;AI 影像編輯器&quot;">​</a></h2><h3 id="ai-編輯器概覽" tabindex="-1">AI 編輯器概覽 <a class="header-anchor" href="#ai-編輯器概覽" aria-label="Permalink to &quot;AI 編輯器概覽&quot;">​</a></h3><p>Nicasa 內建強大的 AI 影像增強工具：</p><ul><li><strong>自動增強</strong>：自動提升畫質</li><li><strong>智慧裁切</strong>：智慧給出裁切建議</li><li><strong>色彩校正</strong>：由 AI 驅動的色彩調整</li><li><strong>降噪</strong>：去除雜點與顆粒</li><li><strong>銳化</strong>：智慧銳化且不產生偽影</li></ul><h3 id="影像修復-inpainting-工具" tabindex="-1">影像修復（Inpainting）工具 <a class="header-anchor" href="#影像修復-inpainting-工具" aria-label="Permalink to &quot;影像修復（Inpainting）工具&quot;">​</a></h3><p>修復工具可以幫你：</p><ul><li>去除圖片中不需要的物體</li><li>智慧填補缺失部分</li><li>修復受損區域</li><li>清理背景</li></ul><h2 id="透明懸浮模式" tabindex="-1">透明懸浮模式 <a class="header-anchor" href="#透明懸浮模式" aria-label="Permalink to &quot;透明懸浮模式&quot;">​</a></h2><p>為設計師與繪師量身打造：</p><ol><li>在 Nicasa 中開啟一張圖片</li><li>從「顯示方式」選單啟用懸浮模式</li><li>使用滑桿調節透明度</li><li>圖片將始終浮於所有其他視窗之上</li><li>可用於描圖、參考對照或 UI 比對</li></ol><h2 id="鍵盤快速鍵" tabindex="-1">鍵盤快速鍵 <a class="header-anchor" href="#鍵盤快速鍵" aria-label="Permalink to &quot;鍵盤快速鍵&quot;">​</a></h2><table tabindex="0"><thead><tr><th>快速鍵</th><th>動作</th></tr></thead><tbody><tr><td><code>Cmd+O</code></td><td>開啟檔案</td></tr><tr><td><code>Cmd+Shift+O</code></td><td>開啟檔案夾</td></tr><tr><td><code>Space</code></td><td>下一張圖片</td></tr><tr><td><code>Shift+Space</code></td><td>上一張圖片</td></tr><tr><td><code>Cmd+F</code></td><td>切換全螢幕</td></tr><tr><td><code>Cmd+W</code></td><td>關閉視窗</td></tr><tr><td><code>Cmd+Q</code></td><td>結束應用程式</td></tr><tr><td><code>Delete</code></td><td>刪除目前圖片</td></tr><tr><td><code>Cmd+S</code></td><td>截圖</td></tr><tr><td><code>Cmd+E</code></td><td>開啟 AI 編輯器</td></tr><tr><td><code>Cmd+T</code></td><td>切換懸浮模式</td></tr></tbody></table><h2 id="chrome-擴充功能整合" tabindex="-1">Chrome 擴充功能整合 <a class="header-anchor" href="#chrome-擴充功能整合" aria-label="Permalink to &quot;Chrome 擴充功能整合&quot;">​</a></h2><h3 id="安裝" tabindex="-1">安裝 <a class="header-anchor" href="#安裝" aria-label="Permalink to &quot;安裝&quot;">​</a></h3><ol><li>安裝 <a href="https://chromewebstore.google.com/detail/nicasa-image-viewer/cihceekeiedkinpjjjfehlgjdhpeokbj" target="_blank" rel="noreferrer">Nicasa Chrome 擴充功能</a></li><li>擴充功能圖示會出現在瀏覽器工具列中</li></ol><h3 id="使用" tabindex="-1">使用 <a class="header-anchor" href="#使用" aria-label="Permalink to &quot;使用&quot;">​</a></h3><ol><li>開啟任意網站</li><li>點擊 Nicasa 擴充功能圖示</li><li>以格狀形式檢視該頁面的所有圖片</li><li>點擊任意圖片，即可在 Nicasa 中開啟</li><li>對網頁圖片使用 Nicasa 的全部功能</li></ol><h2 id="設定" tabindex="-1">設定 <a class="header-anchor" href="#設定" aria-label="Permalink to &quot;設定&quot;">​</a></h2><p>透過 Nicasa &gt; 偏好設定進入設定：</p><ul><li><strong>一般</strong>：預設檔案夾、語言、主題</li><li><strong>檢視</strong>：縮圖尺寸、縮放行為、動畫</li><li><strong>編輯器</strong>：AI 工具偏好、預設增強項目</li><li><strong>擴充功能</strong>：Chrome 擴充功能設定</li><li><strong>隱私權</strong>：資料蒐集偏好</li></ul><h2 id="支援的格式-1" tabindex="-1">支援的格式 <a class="header-anchor" href="#支援的格式-1" aria-label="Permalink to &quot;支援的格式&quot;">​</a></h2><p>Nicasa 支援所有常見圖片格式：</p><ul><li><p><strong>標準格式</strong>：JPEG、PNG、GIF、BMP、TIFF、WebP</p></li><li><p><strong>RAW</strong>：CR2、NEF、ARW、DNG（需轉換）</p></li><li><p><strong>向量</strong>：SVG（需點陣化）</p></li><li><p><strong>動態圖片</strong>：GIF、APNG</p></li><li><p>JPEG/JPG</p></li><li><p>PNG</p></li><li><p>GIF（靜態）</p></li><li><p>BMP</p></li><li><p>TIFF</p></li><li><p>WebP</p></li><li><p>HEIC（在受支援的系統上）</p></li></ul><h2 id="技巧與提示" tabindex="-1">技巧與提示 <a class="header-anchor" href="#技巧與提示" aria-label="Permalink to &quot;技巧與提示&quot;">​</a></h2><ul><li>使用搜尋列按檔案名稱快速尋找圖片</li><li>透過檔案夾整理圖片來建立圖集</li><li>使用評分系統標記你喜歡的圖片</li><li>透過「檔案」選單以不同格式匯出圖片</li></ul>',47)])])}const p=i(r,[["render",o]]);export{u as __pageData,p as default};
